it('shows both real report dates and separate namespace zero groups in a native disclosure', async () => {
  const content = comparisonContent();
  const host = render({ content, request: { target: content.noticias[0], field: 'summary', allowed: [0] } });
  await settle();
  expect(host.querySelector('summary')?.textContent).toContain('ambos cortes');
  expect(host.textContent).toContain('Corte actual: 2026-10-14');
  expect(host.textContent).toContain('Corte comparado: 2026-10-09');
  expect(host.textContent).toContain('current:#0');
  expect(host.textContent).toContain('prior:#0');
  expect(host.querySelectorAll('a')).toHaveLength(2);
  const summary = host.querySelector('summary')!;
  summary.focus();
  expect(document.activeElement).toBe(summary);
  summary.click();
  expect(host.querySelector('details')!.open).toBe(true);
});

it('labels new current-only linkage without implying the prior premise', async () => {
  const content = comparisonContent();
  const item = target();
  item.provenance.summary.catalogue_fingerprint = content.noticias[0].provenance!.summary.catalogue_fingerprint;
  const host = render({ content, request: { target: item, field: 'summary', allowed: [0] } });
  await settle();
  expect(host.querySelector('summary')?.textContent).toBe('Fuentes vinculadas');
  expect(host.textContent).toContain('Corte actual: 2026-10-14');
  expect(host.textContent).not.toContain('Corte comparado');
});


it.each(['javascript:alert(1)', '//medio.test/nota', 'https:///medio.test', 'data:text/html,x'])('keeps unsafe prior URL inert in both-cut disclosure: %s', async url => {
  const content = comparisonContent();
  content.comparison.evidence.sources[0].url = url;
  content.comparison.evidence.sources[0].excerpt = '<img src=x onerror=alert(1)>';
  const context = createEvidenceContext(content);
  const validated = (await context)!;
  const nested = content.noticias[0].provenance!.summary.comparison;
  const priorFingerprint = validated.comparison!.priorFingerprint;
  expect(priorFingerprint).not.toBeNull();
  nested.prior_catalogue_fingerprint = priorFingerprint!;
  nested.context_fingerprint = validated.comparison!.fingerprint;
  const host = render({ context, request: { target: content.noticias[0], field: 'summary', allowed: [0] } });
  await settle();
  expect(host.textContent).toContain('ambos cortes');
  expect(host.querySelectorAll('a')).toHaveLength(1);
  expect(host.querySelector('a')?.getAttribute('href')).toBe('https://medio.test/20/0');
  expect(host.querySelector('img, script')).toBeNull();
  expect(host.textContent).toContain('<img src=x onerror=alert(1)>');
});

it('keeps both-cut source groups unavailable for changed raw prose', async () => {
  const content = comparisonContent();
  content.noticias[0].summary += ' https://x.test/';
  const retained = content.noticias[0].summary;
  const host = render({ content, request: { target: content.noticias[0], field: 'summary', allowed: [0] } });
  await settle();
  expect(host.textContent).toContain('No respaldado');
  expect(host.querySelector('details')).toBeNull();
  expect(content.noticias[0].summary).toBe(retained);
});

it('labels the current report when prior material is explicitly unavailable', async () => {
  const content = {
    date: '2026-10-14', timezone: 'America/Mexico_City', evidence: evidence(),
    comparison: {
      version: 1, available: false, date: null, timezone: null, window_start: null,
      evidence: null, stories: [], current_source_scopes: [[0]], coverage_context: []
    }
  };
  const item = target();
  const context = createEvidenceContext(content);
  const host = render({ context, request: { target: item, field: 'summary', allowed: [0] } });
  await settle();
  expect(host.querySelector('summary')?.textContent).toBe('Fuentes vinculadas');
  expect(host.textContent).toContain('Corte actual: 2026-10-14');
  expect(host.textContent).toContain('current:#0');
  expect(host.textContent).toContain('Fecha de publicación: 24/10/2026 19:30');
  expect(host.textContent).not.toContain('Corte comparado');
  expect(host.textContent).not.toContain('prior:#');
  expect(host.querySelectorAll('a')).toHaveLength(1);
  expect(item.summary).toBe('Lectura política');
  expect((await context)?.comparison?.snapshot.evidence).toBeNull();
  expect((await context)?.comparison?.priorFingerprint).toBeNull();
  // Actual Python comparison_context output for this unavailable-prior input.
  expect((await context)?.comparison?.fingerprint).toBe('a41bc8c5db3cdf8ecffcb47b22cce3521528a6ab542ab7e7d498b8ca4f55fa21');
});

it('resolves reference zero and exposes only recorded publication material', async () => {
  const host = render({ content: { evidence: evidence() }, request: { target: target(), field: 'summary', allowed: [0] } });
  await tick();
  expect(host.textContent).toContain('No respaldado');
  await settle();
  const disclosure = host.querySelector('details');
  expect(disclosure).not.toBeNull();
  expect(disclosure?.querySelector('summary')?.textContent).toBe('Fuentes vinculadas');
  expect(host.textContent).not.toContain('No respaldado');
  expect(host.textContent).toContain('Fecha de publicación: 24/10/2026 19:30');
  expect(host.textContent).toContain('Resumen almacenado (derivado)');
  expect(host.textContent).toContain('Extracto capturado');
  expect(host.textContent).toContain('no verifica la veracidad');
  const link = host.querySelector('a');
  expect(link?.getAttribute('href')).toBe('https://medio.example/nota');
  expect(link?.target).toBe('_blank');
  expect(link?.rel).toBe('noopener noreferrer');
  // Native details/summary owns keyboard activation; no custom button trap.
  const summary = disclosure!.querySelector('summary')!;
  summary.focus();
  expect(document.activeElement).toBe(summary);
  summary.click();
  expect(disclosure!.open).toBe(true);
});

it.each(['javascript:alert(1)', '//medio.example/a', 'https:///medio.example', 'data:text/html,x', 'file:///a'])('renders an unsafe source URL as plain text: %s', async url => {
  const raw = evidence(); raw.sources[0].url = url;
  const context = createEvidenceContext({ evidence: raw });
  const catalogue = (await context)!;
  const item = target(); item.provenance.summary.catalogue_fingerprint = catalogue.fingerprint;
  const host = render({ context, request: { target: item, field: 'summary', allowed: [0] } });
  await settle();
  expect(host.querySelector('summary')?.textContent).toBe('Fuentes vinculadas');
  expect(host.querySelector('a')).toBeNull();
  expect(host.textContent).toContain('Publicación registrada');
});
it('keeps Facebook publication identity without page/group branding or invented dates', async () => {
  const raw = evidence();
  Object.assign(raw.sources[0], { source: 'facebook_page', title: 'Página reservada', author: 'Autor reservado', outlet: 'Grupo reservado', published_at: null, summary: null, excerpt: null });
  const context = createEvidenceContext({ evidence: raw });
  const item = target(); item.provenance.summary.catalogue_fingerprint = (await context)!.fingerprint;
  const host = render({ context, request: { target: item, field: 'summary' } });
  await settle();
  expect(host.textContent).toContain('Publicación de Facebook');
  expect(host.textContent).toContain('Registro #11');
  for (const hidden of ['Página reservada', 'Autor reservado', 'Grupo reservado', 'Fecha de publicación', 'Extracto capturado', 'Resumen almacenado']) expect(host.textContent).not.toContain(hidden);
  expect(host.querySelector('a')?.href).toBe('https://medio.example/nota');
});
it('escapes all frozen material rather than interpreting HTML', async () => {
  const raw = evidence();
  Object.assign(raw.sources[0], { title: '<img src=x onerror=alert(1)>', summary: '<script>alert(1)</script>', excerpt: '<b>Material literal</b>' });
  const context = createEvidenceContext({ evidence: raw });
  const item = target(); item.provenance.summary.catalogue_fingerprint = (await context)!.fingerprint;
  const host = render({ context, request: { target: item, field: 'summary' } });
  await settle();
  expect(host.querySelector('img,script,b')).toBeNull();
  expect(host.textContent).toContain('<b>Material literal</b>');
});
it.each(['pending', 'rejected'])('stays visibly unbacked when validation is %s', async state => {
  const context = state === 'pending' ? new Promise(() => {}) : Promise.reject(new Error('unavailable'));
  const host = render({ context, request: { target: target(), field: 'summary' } });
  await settle();
  expect(host.textContent).toContain('No respaldado');
  expect(host.querySelector('details')).toBeNull();
});

it('does not invent a date from a non-ISO publication value', async () => {
  const raw = evidence(); raw.sources[0].published_at = '0';
  const context = createEvidenceContext({ evidence: raw });
  const item = target(); item.provenance.summary.catalogue_fingerprint = (await context)!.fingerprint;
  const host = render({ context, request: { target: item, field: 'summary' } });
  await settle();
  expect(host.textContent).toContain('Fecha de publicación: 0');
  expect(host.textContent).not.toContain('2000');
});

it('wraps long captured URLs without dropping recorded material', async () => {
  const raw = evidence();
  const captured = ('https://ejemplo.invalid/documento/' + 'a'.repeat(300)).slice(0, 300);
  raw.sources[0].excerpt = captured;
  const context = createEvidenceContext({ evidence: raw });
  const item = target();
  item.provenance.summary.catalogue_fingerprint = (await context)!.fingerprint;
  // Vitest does not inject component CSS; apply the actual stylesheet to the public DOM.
  const source = readFileSync(join(dirname(fileURLToPath(import.meta.url)), 'DigestEvidence.svelte'), 'utf8');
  const style = document.createElement('style');
  style.textContent = source.match(/<style>([\s\S]*?)<\/style>/)![1];
  document.head.append(style);
  try {
    const host = render({ context, request: { target: item, field: 'summary', allowed: [0] } });
    await settle();
    host.querySelector('details')!.open = true;
    const material = host.querySelector('.digest-provenance-material')!;
    expect(material.textContent).toContain(captured);
    expect(getComputedStyle(material).overflowWrap).toBe('anywhere');
  } finally {
    style.remove();
  }
});
